import{_ as d,o as a,c as r,ag as e}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"2026年6月风电新能源深度：深远海破局，储能十万亿","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/wind-energy/2026-june-offshore-breakthrough.md","filePath":"topics/wind-energy/2026-june-offshore-breakthrough.md"}'),o={name:"topics/wind-energy/2026-june-offshore-breakthrough.md"};function h(l,t,i,n,s,u){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_2026年6月风电新能源深度-深远海破局-储能十万亿" tabindex="-1">2026年6月风电新能源深度：深远海破局，储能十万亿 <a class="header-anchor" href="#_2026年6月风电新能源深度-深远海破局-储能十万亿" aria-label="Permalink to &quot;2026年6月风电新能源深度：深远海破局，储能十万亿&quot;">​</a></h1><blockquote><p>来源：央视新闻、南方+、国务院国资委、国家能源局、InfoLink、证券时报、SNE Research 日期：2026-06-30</p></blockquote><hr><h2 id="一、深远海浮式风电-从实验室到商业化" tabindex="-1">一、深远海浮式风电：从实验室到商业化 <a class="header-anchor" href="#一、深远海浮式风电-从实验室到商业化" aria-label="Permalink to &quot;一、深远海浮式风电：从实验室到商业化&quot;">​</a></h2><h3 id="海油安澜号-6月28日出港" tabindex="-1">海油安澜号（6月28日出港） <a class="header-anchor" href="#海油安澜号-6月28日出港" aria-label="Permalink to &quot;海油安澜号（6月28日出港）&quot;">​</a></h3><p><strong>全球首座16MW张力腿浮式风电平台</strong>，从珠海高栏港启程，向粤东陆丰油田群海域进发。</p><table tabindex="0"><thead><tr><th>参数</th><th>数值</th></tr></thead><tbody><tr><td>总高</td><td>307米</td></tr><tr><td>总重</td><td>约8000吨</td></tr><tr><td>单机容量</td><td>16MW</td></tr><tr><td>年均发电量</td><td>5400万千瓦时</td></tr><tr><td>年减排CO₂</td><td>约3.5万吨</td></tr><tr><td>年节约燃料油</td><td>约1.5万立方米</td></tr></tbody></table><p><strong>三大突破</strong>：</p><ol><li><strong>100%国产化</strong>：从概念设计、核心装备制造到一体化总装全链条国产化</li><li><strong>TLP张力腿结构</strong>：17级强台风工况整体倾斜不超过1°，远优于半潜式方案</li><li><strong>&quot;风电+海上油气&quot;一体化</strong>：电力直供采油平台，开创协同减碳全新路径</li></ol><p>海外同规格浮式平台造价是国产版本2.5倍。依托国内完整产业链，浮式风电建设成本每年稳定下降15%，行业测算<strong>2028年即可实现无补贴平价上网</strong>。</p><h3 id="中广核阳江帆石二-6月2日" tabindex="-1">中广核阳江帆石二（6月2日） <a class="header-anchor" href="#中广核阳江帆石二-6月2日" aria-label="Permalink to &quot;中广核阳江帆石二（6月2日）&quot;">​</a></h3><p><strong>全国首次18MW级海上风机规模化应用</strong>。</p><table tabindex="0"><thead><tr><th>参数</th><th>数值</th></tr></thead><tbody><tr><td>总装机</td><td>100万千瓦</td></tr><tr><td>风机配置</td><td>25台×16.2MW + 33台×18MW</td></tr><tr><td>叶轮直径</td><td>292米</td></tr><tr><td>单支叶片</td><td>143米</td></tr><tr><td>扫风面积</td><td>6.6万㎡≈9个足球场</td></tr><tr><td>转一圈发电</td><td>约43度（够1个家庭用9天）</td></tr><tr><td>单台年发电</td><td>5600万千瓦时</td></tr><tr><td>整机吊装重量</td><td>超1500吨</td></tr><tr><td>轮毂中心高度</td><td>171.9米（57层楼）</td></tr></tbody></table><h3 id="华能-睿风号-6月4日启动" tabindex="-1">华能&quot;睿风号&quot;（6月4日启动） <a class="header-anchor" href="#华能-睿风号-6月4日启动" aria-label="Permalink to &quot;华能&quot;睿风号&quot;（6月4日启动）&quot;">​</a></h3><p><strong>全球单机容量最大的17MW直驱型漂浮式海上风电机组</strong>。</p><p>三大技术创新：</p><ul><li>一体化设计，单位千瓦造价较已建项目<strong>降低25%以上</strong></li><li>智能控制系统抑制浮体摇摆，<strong>提升发电量超3%</strong></li><li>首创一体化仿真与混合模型水池试验技术，填补国内行业标准空白</li></ul><p>可抵御17级超强台风、应对24米超高海浪。</p><hr><h2 id="二、金风科技-6月多重催化" tabindex="-1">二、金风科技：6月多重催化 <a class="header-anchor" href="#二、金风科技-6月多重催化" aria-label="Permalink to &quot;二、金风科技：6月多重催化&quot;">​</a></h2><h3 id="涨停-6月30日" tabindex="-1">涨停（6月30日） <a class="header-anchor" href="#涨停-6月30日" aria-label="Permalink to &quot;涨停（6月30日）&quot;">​</a></h3><p>收盘23.9元，当日涨停。</p><h3 id="近期催化剂" tabindex="-1">近期催化剂 <a class="header-anchor" href="#近期催化剂" aria-label="Permalink to &quot;近期催化剂&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>事件</th></tr></thead><tbody><tr><td>6月27日</td><td>中标国家电投2.15GW陆上风电项目，规模创近年单批次纪录</td></tr><tr><td>6月</td><td>首台国产化16MW海上风电机组完成吊装并网，核心部件自主可控</td></tr><tr><td>6月</td><td>沙特PIF5 3GW项目首批设备发运，全球最大陆上风电项目进入交付阶段</td></tr><tr><td>6月</td><td>公司调研透露：在手订单覆盖今明两年，上半年与下半年均衡交付</td></tr></tbody></table><h3 id="沙特项目细节" tabindex="-1">沙特项目细节 <a class="header-anchor" href="#沙特项目细节" aria-label="Permalink to &quot;沙特项目细节&quot;">​</a></h3><ul><li>为沙特定制GWH204-10MW机型</li><li>148米钢混塔架可耐受50℃极端高温</li><li>全球最大陆上风电项目</li></ul><hr><h2 id="三、储能-十万亿新赛道" tabindex="-1">三、储能：十万亿新赛道 <a class="header-anchor" href="#三、储能-十万亿新赛道" aria-label="Permalink to &quot;三、储能：十万亿新赛道&quot;">​</a></h2><h3 id="达沃斯定调" tabindex="-1">达沃斯定调 <a class="header-anchor" href="#达沃斯定调" aria-label="Permalink to &quot;达沃斯定调&quot;">​</a></h3><p>2026年达沃斯论坛，《2026年十大新兴技术》榜首：<strong>&quot;万物互联电网&quot;</strong>。约70%参会者认为能源和电网容量将成为未来五年制约AI增长的主要瓶颈。</p><h3 id="市场规模" tabindex="-1">市场规模 <a class="header-anchor" href="#市场规模" aria-label="Permalink to &quot;市场规模&quot;">​</a></h3><p>海辰储能董事长吴祖钰：</p><blockquote><p>当风光发电+储能+输配电成本都达到每千瓦时0.1元时，绿色能源综合成本进入&quot;三毛钱时代&quot;，经济性全面超越传统能源。预计2030年全球储能产业链市场规模达<strong>10万亿元级别</strong>。</p></blockquote><h3 id="装机数据" tabindex="-1">装机数据 <a class="header-anchor" href="#装机数据" aria-label="Permalink to &quot;装机数据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>数据</th><th>同比</th></tr></thead><tbody><tr><td>全球新型储能累计装机</td><td>277.7GW / 679.6GWh</td><td>+68.1% / +84.2%</td></tr><tr><td>全球新增装机</td><td>112.5GW / 310.6GWh</td><td>+51.6% / +77.5%</td></tr><tr><td>中国新型储能累计装机</td><td>136GW / 351GWh</td><td>+84.38% / +108.93%</td></tr><tr><td>Q1 2026全球储能电芯出货</td><td>205.52GWh</td><td>+98.7%</td></tr></tbody></table><h3 id="竞争格局" tabindex="-1">竞争格局 <a class="header-anchor" href="#竞争格局" aria-label="Permalink to &quot;竞争格局&quot;">​</a></h3><p>Q1 2026全球储能电芯出货前五：</p><table tabindex="0"><thead><tr><th>排名</th><th>企业</th><th>市占率（CR5≈59%）</th></tr></thead><tbody><tr><td>1</td><td>宁德时代</td><td>约40%</td></tr><tr><td>2</td><td>海辰储能</td><td>—</td></tr><tr><td>3</td><td>亿纬锂能</td><td>—</td></tr><tr><td>4</td><td>比亚迪储能</td><td>—</td></tr><tr><td>5</td><td>中创新航</td><td>—</td></tr></tbody></table><p>行业集中度CR10为85.2%。</p><hr><h2 id="四、陆上风电-大机组时代" tabindex="-1">四、陆上风电：大机组时代 <a class="header-anchor" href="#四、陆上风电-大机组时代" aria-label="Permalink to &quot;四、陆上风电：大机组时代&quot;">​</a></h2><h3 id="行业格局" tabindex="-1">行业格局 <a class="header-anchor" href="#行业格局" aria-label="Permalink to &quot;行业格局&quot;">​</a></h3><ul><li>前五月风电开标，中国电建一家占央国企总规模51.58%</li><li>6.25MW是绝对主力机型</li><li>10MW级陆上风机已批量落地</li><li>6月中船科技完成国内首台15MW陆上风电机组总装</li><li>运达和东方风电咬得很紧，远景能源5月冲到第三</li></ul><h3 id="金风科技行业地位" tabindex="-1">金风科技行业地位 <a class="header-anchor" href="#金风科技行业地位" aria-label="Permalink to &quot;金风科技行业地位&quot;">​</a></h3><ul><li>在手订单覆盖今明两年</li><li>上半年与下半年均衡交付</li><li>16MW海上风机国产化突破</li><li>沙特3GW项目出海标杆</li></ul><hr><h2 id="五、动力电池-中国统治级表现" tabindex="-1">五、动力电池：中国统治级表现 <a class="header-anchor" href="#五、动力电池-中国统治级表现" aria-label="Permalink to &quot;五、动力电池：中国统治级表现&quot;">​</a></h2><p>2026年1-4月全球动力电池装机量（SNE Research）：</p><table tabindex="0"><thead><tr><th>排名</th><th>企业</th><th>装机量</th><th>市占率</th></tr></thead><tbody><tr><td>1</td><td>宁德时代</td><td>141.4GWh</td><td>40.1%</td></tr><tr><td>2</td><td>比亚迪</td><td>50.0GWh</td><td>14.2%</td></tr><tr><td>—</td><td>中国7家合计</td><td>—</td><td>54.3%</td></tr></tbody></table><p>全球前十7家中国企业。宁德时代推出新款电池，充电不到10分钟跑400公里，充电速度约为当前多数电动车电池的3倍。</p><hr><h2 id="六、关键趋势总结" tabindex="-1">六、关键趋势总结 <a class="header-anchor" href="#六、关键趋势总结" aria-label="Permalink to &quot;六、关键趋势总结&quot;">​</a></h2><ol><li><strong>深远海风电从示范迈向商业化</strong>：16MW浮式+18MW固定式同月突破，2028年平价可期</li><li><strong>浮式风电国产化成本优势显著</strong>：造价仅为海外2.5折，每年下降15%</li><li><strong>金风科技多重催化</strong>：中标2.15GW+沙特3GW出海+16MW国产化，涨停</li><li><strong>储能从&quot;强制配储&quot;到&quot;AI基座&quot;</strong>：2030年十万亿赛道，中国装机量全球领先</li><li><strong>动力电池中国统治</strong>：宁德时代40%全球市占率，7家中国企业合计54%</li><li><strong>陆上风电进入15MW时代</strong>：大机组降本趋势不可逆，行业集中度提升中</li></ol>',53)])])}const q=d(o,[["render",h]]);export{c as __pageData,q as default};
